/**
 * Podcast Commerce Extractor — Apify Actor
 *
 * Thin wrapper around podcast-commerce-mcp (sincetoday.workers.dev).
 * Accepts a podcast transcript or URL, returns structured product data.
 *
 * Endpoint: https://podcast-commerce-mcp.sincetoday.workers.dev/mcp
 * Protocol: MCP Streamable HTTP (JSON-RPC 2.0 over POST)
 */

import { Actor } from "apify";

const MCP_ENDPOINT = "https://podcast-commerce-mcp.sincetoday.workers.dev/mcp";
const TRANSCRIPT_MAX_CHARS = 100_000;

async function fetchTranscriptFromUrl(url) {
  const resp = await fetch(url, {
    headers: { "User-Agent": "ApifyActor/podcast-commerce-mcp" },
  });
  if (!resp.ok) throw new Error(`Failed to fetch URL ${url}: HTTP ${resp.status}`);
  const html = await resp.text();
  // Strip HTML tags — best-effort transcript extraction from page source
  return html
    .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, "")
    .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, "")
    .replace(/<[^>]+>/g, " ")
    .replace(/\s+/g, " ")
    .trim()
    .slice(0, TRANSCRIPT_MAX_CHARS);
}

async function callMcp(toolName, args) {
  const body = {
    jsonrpc: "2.0",
    id: 1,
    method: "tools/call",
    params: {
      name: toolName,
      arguments: args,
    },
  };

  const resp = await fetch(MCP_ENDPOINT, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Accept: "application/json, text/event-stream",
    },
    body: JSON.stringify(body),
  });

  if (!resp.ok) {
    const text = await resp.text().catch(() => "");
    throw new Error(`MCP endpoint error HTTP ${resp.status}: ${text.slice(0, 200)}`);
  }

  const contentType = resp.headers.get("content-type") ?? "";

  // Handle SSE streaming response
  if (contentType.includes("text/event-stream")) {
    const text = await resp.text();
    const lines = text.split("\n").filter((l) => l.startsWith("data: "));
    for (const line of lines.reverse()) {
      try {
        const data = JSON.parse(line.slice(6));
        if (data.result) return data.result;
        if (data.error) throw new Error(`MCP error: ${JSON.stringify(data.error)}`);
      } catch {
        // skip unparseable lines
      }
    }
    throw new Error("No result found in SSE stream");
  }

  // Handle JSON response
  const data = await resp.json();
  if (data.error) throw new Error(`MCP error: ${JSON.stringify(data.error)}`);
  return data.result;
}

function parseProductsFromResult(result) {
  // MCP result is { content: [{ type: 'text', text: '<json string>' }] }
  if (!result?.content?.length) return null;
  const textContent = result.content.find((c) => c.type === "text");
  if (!textContent?.text) return null;
  try {
    return JSON.parse(textContent.text);
  } catch {
    return { raw: textContent.text };
  }
}

await Actor.init();

try {
  const input = await Actor.getInput();

  // Validate input
  if (!input?.transcriptText && !input?.podcastUrl) {
    throw new Error("Input must provide either 'transcriptText' or 'podcastUrl'.");
  }

  let transcript = input.transcriptText ?? "";

  // Fetch transcript from URL if provided
  if (!transcript && input.podcastUrl) {
    console.log(`Fetching transcript from URL: ${input.podcastUrl}`);
    transcript = await fetchTranscriptFromUrl(input.podcastUrl);
    console.log(`Fetched ${transcript.length} chars from URL.`);
  }

  if (!transcript.trim()) {
    throw new Error("Transcript is empty. Provide 'transcriptText' or a URL with transcript content.");
  }

  const episodeId = input.episodeId ?? `actor-run-${Date.now()}`;
  const showName = input.showName ?? "";
  const categoryFilter = input.categoryFilter ?? [];
  const minConfidence = input.minConfidence ?? 0;

  console.log(`Calling extract_podcast_products — episode: ${episodeId}`);

  const mcpArgs = {
    transcript: transcript.slice(0, TRANSCRIPT_MAX_CHARS),
    episode_id: episodeId,
    ...(showName && { show_name: showName }),
    ...(categoryFilter.length && { category_filter: categoryFilter }),
  };

  const result = await callMcp("extract_podcast_products", mcpArgs);
  const products = parseProductsFromResult(result);

  if (!products) {
    console.warn("No structured product data in response — saving raw result.");
    await Actor.pushData({ raw_result: result });
    await Actor.exit();
    process.exit(0);
  }

  // Filter by confidence if requested
  const productList = Array.isArray(products.products) ? products.products : [];
  const filtered =
    minConfidence > 0
      ? productList.filter((p) => (p.confidence ?? 0) >= minConfidence)
      : productList;

  // Push each product as a separate dataset item (Apify best practice for crawlers)
  if (filtered.length > 0) {
    await Actor.pushData(filtered);
    console.log(`Pushed ${filtered.length} products to dataset.`);
  } else {
    console.log("No products found (or all filtered by minConfidence).");
    await Actor.pushData({
      episode_id: episodeId,
      products: [],
      message: "No product mentions found in transcript.",
    });
  }

  // Charge for extraction (Pay-per-event pricing — 1 event per successful run)
  await Actor.charge({ eventName: "extraction", count: 1 });

  // Also save summary metadata
  const summary = {
    episode_id: episodeId,
    show_name: showName || null,
    total_products: filtered.length,
    ...(products.extraction_stats && { extraction_stats: products.extraction_stats }),
    ...(products.episode_summary && { episode_summary: products.episode_summary }),
    source: "podcast-commerce-mcp@sincetoday.workers.dev",
  };
  console.log("Summary:", JSON.stringify(summary, null, 2));
} catch (err) {
  console.error("Actor failed:", err.message);
  await Actor.fail(err.message);
}

await Actor.exit();

import { defineConfig } from "vitest/config";
export default defineConfig({
  test: {
    environment: "node",
    include: ["tests/**/*.test.ts"],
    // Rebuild better-sqlite3 before tests — prevents binary drift after nvm switches.
    globalSetup: ["./tests/setup/rebuild-sqlite.ts"],
    // Serialize test files to eliminate SQLite write contention.
    // pool:"forks" + maxWorkers:1 replaces the removed poolOptions.forks.singleFork (Vitest 4).
    pool: "forks",
    maxWorkers: 1,
    // Cold fork load of better-sqlite3 native module can exceed 5s default.
    testTimeout: 15000,
  },
});

/**
 * Podcast Commerce MCP — Eval Framework Types
 *
 * Quality evaluation for extraction accuracy on real-world podcast transcripts.
 * Three modes:
 *   fixture  — mocked extractor, tests scoring logic and schema correctness
 *   live     — real OpenAI calls, validates extraction quality on real content
 *   snapshot — update golden snapshots from live output
 */

import type { ProductMention } from "../src/types.js";

// ============================================================================
// EVAL CASE
// ============================================================================

export interface ExpectedProduct {
  /** Exact or partial product name match (case-insensitive) */
  name: string;
  /** Expected category */
  category: string;
  /** Must be present in output — failure if missing */
  required: boolean;
}

export interface PodcastEvalCase {
  id: string;
  name: string;
  /** Data provenance — where the transcript was sourced from */
  source: string;
  /** Full transcript text (real content from source) */
  transcript: string;
  /** Products we expect extraction to identify */
  expectedProducts: ExpectedProduct[];
  /** Max token budget for JSON output (default: 2000) */
  maxTokens?: number;
}

// ============================================================================
// EVAL RESULT
// ============================================================================

export interface ScorerResult {
  dimension: string;
  score: number;   // 0-100
  target: number;  // pass threshold
  details: string;
  passed: boolean;
}

export interface EvalResult {
  caseId: string;
  caseName: string;
  timestamp: string;
  scores: ScorerResult[];
  overallScore: number;
  passed: boolean;
  productsExtracted: ProductMention[];
}

/**
 * Podcast Commerce MCP — Eval Runner
 *
 * Usage:
 *   npx tsx tests/eval-runner.ts               # fixture mode (mocked extractor)
 *   EVAL_LIVE=true npx tsx tests/eval-runner.ts # live mode (real OpenAI API)
 *
 * Fixture mode: injects a deterministic mock that returns all expectedProducts.
 * Live mode: calls extractProducts() with real OpenAI key from env.
 */

import type { PodcastEvalCase, EvalResult } from "./eval-types.js";
import { ALL_SCORERS } from "./eval-scorers.js";
import { ALL_CASES } from "./eval-cases/index.js";
import type { ExtractionResult } from "../src/types.js";

// ---------------------------------------------------------------------------
// Fixture mock — returns expectedProducts as ProductMentions
// ---------------------------------------------------------------------------

function mockExtraction(evalCase: PodcastEvalCase): ExtractionResult {
  return {
    episode_id: evalCase.id,
    products: evalCase.expectedProducts.map((ep) => ({
      name: ep.name,
      category: ep.category,
      confidence: 0.9,
      mention_context: "Mock extraction for fixture mode",
      recommendation_strength: "mentioned",
      affiliate_link: null,
    })),
    sponsor_segments: [],
    total_products: evalCase.expectedProducts.length,
    ai_cost_usd: 0,
  } as unknown as ExtractionResult;
}

// ---------------------------------------------------------------------------
// Runner
// ---------------------------------------------------------------------------

async function runCase(
  evalCase: PodcastEvalCase,
  mode: "fixture" | "live"
): Promise<EvalResult> {
  const start = Date.now();
  let result: ExtractionResult;

  if (mode === "live") {
    const { extractProducts } = await import("../src/extractor.js");
    const extracted = await extractProducts({ transcript: evalCase.transcript });
    result = { ...extracted, _meta: { processing_time_ms: 0, ai_cost_usd: extracted.ai_cost_usd, cache_hit: false } } as unknown as ExtractionResult;
  } else {
    result = mockExtraction(evalCase);
  }

  const scores = ALL_SCORERS.map((scorer) => scorer(evalCase, result));
  const overallScore = Math.round(scores.reduce((s, r) => s + r.score, 0) / scores.length);

  return {
    caseId: evalCase.id,
    caseName: evalCase.name,
    timestamp: new Date().toISOString(),
    scores,
    overallScore,
    passed: scores.every((s) => s.passed),
    productsExtracted: result.products ?? [],
  };
}

async function main() {
  const mode = process.env.EVAL_LIVE === "true" ? "live" : "fixture";
  console.log(`\n🧪 Podcast Commerce MCP — Eval (mode: ${mode})\n`);

  const results: EvalResult[] = [];
  for (const evalCase of ALL_CASES) {
    process.stdout.write(`  ${evalCase.name}... `);
    try {
      const result = await runCase(evalCase, mode);
      results.push(result);
      const icon = result.passed ? "✅" : "❌";
      console.log(`${icon} ${result.overallScore}/100`);
      for (const s of result.scores) {
        const icon2 = s.passed ? "✓" : "✗";
        console.log(`     ${icon2} ${s.dimension}: ${s.score}/${s.target} — ${s.details}`);
      }
    } catch (err) {
      console.log(`💥 ERROR: ${err instanceof Error ? err.message : String(err)}`);
    }
  }

  const passed = results.filter((r) => r.passed).length;
  const avg = results.length > 0 ? Math.round(results.reduce((s, r) => s + r.overallScore, 0) / results.length) : 0;
  console.log(`\n📊 ${passed}/${results.length} cases passed. Average score: ${avg}/100\n`);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

/**
 * Tests for episode-comparator.ts
 * Covers computeTrendingProducts and compareEpisodes — previously untested.
 */

import { describe, it, expect } from "vitest";
import {
  computeTrendingProducts,
  compareEpisodes,
} from "../src/episode-comparator.js";

function makeProduct(name: string, strength: string) {
  return {
    name,
    category: "supplement",
    recommendation_strength: strength,
    confidence: 0.9,
    speaker: "host" as const,
    mention_context: `context for ${name}`,
    affiliate_link: null,
    mention_count: 1,
  };
}

function makeEp(id: string, products: ReturnType<typeof makeProduct>[]) {
  return {
    episode_id: id,
    products,
    sponsor_segments: [],
    _meta: { processing_time_ms: 100, ai_cost_usd: 0.001, cache_hit: false },
  };
}

describe("computeTrendingProducts", () => {
  it("returns empty array for no episodes", () => {
    expect(computeTrendingProducts([])).toEqual([]);
  });

  it("avg_recommendation_strength is finite for single episode", () => {
    const result = computeTrendingProducts([makeEp("ep1", [makeProduct("AG1", "strong")])]);
    expect(result).toHaveLength(1);
    expect(Number.isFinite(result[0]!.avg_recommendation_strength)).toBe(true);
    expect(result[0]!.avg_recommendation_strength).toBe(3); // strong = 3
  });

  it("avg_recommendation_strength is finite for multi-episode products", () => {
    const eps = [
      makeEp("ep1", [makeProduct("AG1", "strong")]),   // 3
      makeEp("ep2", [makeProduct("AG1", "moderate")]), // 2
    ];
    const result = computeTrendingProducts(eps);
    expect(result).toHaveLength(1);
    expect(result[0]!.mention_count).toBe(2);
    expect(Number.isFinite(result[0]!.avg_recommendation_strength)).toBe(true);
    expect(result[0]!.avg_recommendation_strength).toBe(2.5); // (3+2)/2
  });

  it("sorts by mention_count descending", () => {
    const eps = [
      makeEp("ep1", [makeProduct("AG1", "strong"), makeProduct("Oura", "mention")]),
      makeEp("ep2", [makeProduct("AG1", "moderate")]),
    ];
    const result = computeTrendingProducts(eps);
    expect(result[0]!.name).toBe("AG1");
    expect(result[0]!.mention_count).toBe(2);
  });
});

describe("compareEpisodes", () => {
  it("returns empty result for no episodes", () => {
    const r = compareEpisodes([], "all");
    expect(r.new_products).toHaveLength(0);
    expect(r.dropped_products).toHaveLength(0);
  });

  it("identifies products new to the latest episode", () => {
    const eps = [
      makeEp("ep1", [makeProduct("AG1", "strong")]),
      makeEp("ep2", [makeProduct("Oura", "moderate")]),
    ];
    const r = compareEpisodes(eps, "new_in_latest");
    expect(r.new_products).toContain("Oura");
    expect(r.dropped_products).toHaveLength(0);
  });
});

/**
 * Unit tests for show-notes-formatter.ts
 *
 * Pure formatting logic — no mocks or OpenAI calls needed.
 */

import { describe, it, expect } from "vitest";
import { generateShowNotes } from "../src/show-notes-formatter.js";
import type { ProductMention } from "../src/types.js";

const makeProduct = (overrides: Partial<ProductMention>): ProductMention => ({
  name: "Test Product",
  category: "physical_goods",
  mention_context: "Host said this product changed their life",
  speaker: "host",
  confidence: 0.9,
  recommendation_strength: "strong",
  affiliate_link: null,
  mention_count: 1,
  ...overrides,
});

const SAMPLE_PRODUCTS: ProductMention[] = [
  makeProduct({ name: "Athletic Greens AG1", recommendation_strength: "strong", affiliate_link: "https://ag1.com/ref" }),
  makeProduct({ name: "Momentous Protein", recommendation_strength: "moderate", confidence: 0.85 }),
  makeProduct({ name: "Iron Flask Bottle", recommendation_strength: "mention", confidence: 0.7 }),
  makeProduct({ name: "Bad Product", recommendation_strength: "negative", confidence: 0.8 }),
  makeProduct({ name: "Low Confidence", recommendation_strength: "strong", confidence: 0.4 }),
];

describe("generateShowNotes — markdown minimal", () => {
  it("returns a product list with affiliate link when present", () => {
    const result = generateShowNotes(SAMPLE_PRODUCTS, "markdown", "minimal");
    expect(result).toContain("[Athletic Greens AG1](https://ag1.com/ref)");
    expect(result).toContain("## Mentioned Products");
  });

  it("renders products without links as bold name", () => {
    const result = generateShowNotes(SAMPLE_PRODUCTS, "markdown", "minimal");
    expect(result).toContain("**Momentous Protein**");
  });

  it("excludes negative recommendations", () => {
    const result = generateShowNotes(SAMPLE_PRODUCTS, "markdown", "minimal");
    expect(result).not.toContain("Bad Product");
  });

  it("excludes low confidence products (< 0.6)", () => {
    const result = generateShowNotes(SAMPLE_PRODUCTS, "markdown", "minimal");
    expect(result).not.toContain("Low Confidence");
  });
});

describe("generateShowNotes — markdown full", () => {
  it("groups by endorsement strength with headers", () => {
    const result = generateShowNotes(SAMPLE_PRODUCTS, "markdown", "full");
    expect(result).toContain("### ⭐ Strong Endorsements");
    expect(result).toContain("### 👍 Recommendations");
  });

  it("includes mention context quote", () => {
    const result = generateShowNotes(SAMPLE_PRODUCTS, "markdown", "full");
    expect(result).toContain("changed their life");
  });

  it("includes CTA line", () => {
    const result = generateShowNotes(SAMPLE_PRODUCTS, "markdown", "full");
    expect(result).toContain("Affiliate links support the creator");
  });
});

describe("generateShowNotes — html", () => {
  it("returns html tags for minimal format", () => {
    const result = generateShowNotes(SAMPLE_PRODUCTS, "html", "minimal");
    expect(result).toContain("<h2>Mentioned Products</h2>");
    expect(result).toContain("<ul>");
    expect(result).toContain('<a href="https://ag1.com/ref">Athletic Greens AG1</a>');
  });

  it("returns html tags for full format", () => {
    const result = generateShowNotes(SAMPLE_PRODUCTS, "html", "full");
    expect(result).toContain("<h2>Products Mentioned in This Episode</h2>");
    expect(result).toContain("<h3>⭐ Strong Endorsements</h3>");
  });
});

describe("generateShowNotes — empty / edge cases", () => {
  it("handles empty product array gracefully", () => {
    const result = generateShowNotes([], "markdown", "full");
    expect(result).toContain("No significant product mentions");
  });

  it("handles all-negative products gracefully", () => {
    const negativeOnly = [makeProduct({ recommendation_strength: "negative" })];
    const result = generateShowNotes(negativeOnly, "markdown", "full");
    expect(result).toContain("No significant product mentions");
  });

  it("sorts strong endorsements before moderate", () => {
    const result = generateShowNotes(SAMPLE_PRODUCTS, "markdown", "minimal");
    const agIdx = result.indexOf("Athletic Greens AG1");
    const momentousIdx = result.indexOf("Momentous Protein");
    expect(agIdx).toBeLessThan(momentousIdx);
  });
});

/**
 * Input size limit tests (FIND-4).
 *
 * Verifies that the Zod schemas in server.ts enforce the expected upper bounds
 * on all user-supplied fields that reach OpenAI. Each test imports the exported
 * limit constants so the assertions stay in sync with the implementation.
 */

import { describe, it, expect } from "vitest";
import { z } from "zod";
import {
  TRANSCRIPT_MAX_CHARS,
  ID_MAX_CHARS,
  API_KEY_MAX_CHARS,
  CATEGORY_FILTER_ITEM_MAX,
  CATEGORY_FILTER_ARRAY_MAX,
  EPISODE_IDS_ARRAY_MAX,
} from "../src/server.js";

// ============================================================================
// transcript (extract_podcast_products, analyze_episode_sponsors)
// ============================================================================

describe("transcript field limits", () => {
  const schema = z.string().min(1).max(TRANSCRIPT_MAX_CHARS);

  it("accepts a transcript at the exact max length", () => {
    expect(schema.safeParse("x".repeat(TRANSCRIPT_MAX_CHARS)).success).toBe(true);
  });

  it("rejects a transcript one character over the limit", () => {
    const result = schema.safeParse("x".repeat(TRANSCRIPT_MAX_CHARS + 1));
    expect(result.success).toBe(false);
  });

  it("rejects an empty transcript", () => {
    expect(schema.safeParse("").success).toBe(false);
  });
});

// ============================================================================
// episode_id / id fields
// ============================================================================

describe("ID field limits", () => {
  const schema = z.string().max(ID_MAX_CHARS).optional();

  it("accepts an ID at the exact max length", () => {
    expect(schema.safeParse("a".repeat(ID_MAX_CHARS)).success).toBe(true);
  });

  it("rejects an ID one character over the limit", () => {
    const result = schema.safeParse("a".repeat(ID_MAX_CHARS + 1));
    expect(result.success).toBe(false);
  });

  it("accepts undefined (optional)", () => {
    expect(schema.safeParse(undefined).success).toBe(true);
  });
});

// ============================================================================
// api_key field
// ============================================================================

describe("api_key field limits", () => {
  const schema = z.string().max(API_KEY_MAX_CHARS).optional();

  it("accepts an api_key at the exact max length", () => {
    expect(schema.safeParse("k".repeat(API_KEY_MAX_CHARS)).success).toBe(true);
  });

  it("rejects an api_key one character over the limit", () => {
    const result = schema.safeParse("k".repeat(API_KEY_MAX_CHARS + 1));
    expect(result.success).toBe(false);
  });
});

// ============================================================================
// category_filter array
// ============================================================================

describe("category_filter array limits", () => {
  const schema = z
    .array(z.string().max(CATEGORY_FILTER_ITEM_MAX))
    .max(CATEGORY_FILTER_ARRAY_MAX)
    .optional();

  it("accepts an array at the max item count", () => {
    const input = Array.from({ length: CATEGORY_FILTER_ARRAY_MAX }, (_, i) => `cat${i}`);
    expect(schema.safeParse(input).success).toBe(true);
  });

  it("rejects an array one item over the max count", () => {
    const input = Array.from({ length: CATEGORY_FILTER_ARRAY_MAX + 1 }, (_, i) => `cat${i}`);
    expect(schema.safeParse(input).success).toBe(false);
  });

  it("rejects a category string over the item max length", () => {
    const input = ["c".repeat(CATEGORY_FILTER_ITEM_MAX + 1)];
    expect(schema.safeParse(input).success).toBe(false);
  });

  it("accepts undefined (optional)", () => {
    expect(schema.safeParse(undefined).success).toBe(true);
  });
});

// ============================================================================
// episode_ids array (track_product_trends)
// ============================================================================

describe("episode_ids array limits", () => {
  const schema = z
    .array(z.string().max(ID_MAX_CHARS))
    .min(1)
    .max(EPISODE_IDS_ARRAY_MAX);

  it("accepts an array at the max count", () => {
    const input = Array.from({ length: EPISODE_IDS_ARRAY_MAX }, (_, i) => `ep-${i}`);
    expect(schema.safeParse(input).success).toBe(true);
  });

  it("rejects an array one item over the max count", () => {
    const input = Array.from({ length: EPISODE_IDS_ARRAY_MAX + 1 }, (_, i) => `ep-${i}`);
    expect(schema.safeParse(input).success).toBe(false);
  });

  it("rejects an episode ID over the ID max length", () => {
    const input = ["x".repeat(ID_MAX_CHARS + 1)];
    expect(schema.safeParse(input).success).toBe(false);
  });

  it("rejects an empty array (min 1)", () => {
    expect(schema.safeParse([]).success).toBe(false);
  });
});

