/**
 * Analysis Cache — SQLite-backed cache for episode extraction results.
 *
 * Stores EpisodeExtraction objects keyed by episode_id.
 * Uses better-sqlite3 for synchronous, thread-safe operations.
 *
 * Table: episode_cache
 *   episode_id TEXT PRIMARY KEY
 *   data       TEXT NOT NULL  (JSON-serialized EpisodeExtraction)
 *   created_at INTEGER NOT NULL  (Unix timestamp)
 */

import Database from "better-sqlite3";
import { existsSync, mkdirSync } from "node:fs";
import { dirname, resolve } from "node:path";
import type { EpisodeExtraction } from "./types.js";

// ============================================================================
// CONSTANTS
// ============================================================================

const DEFAULT_DB_PATH = "./data/cache.db";

// ============================================================================
// CACHE INTERFACE
// ============================================================================

export interface AnalysisCacheStore {
  get(episodeId: string): EpisodeExtraction | null;
  set(episodeId: string, data: EpisodeExtraction): void;
  getAll(): EpisodeExtraction[];
}

// ============================================================================
// IMPLEMENTATION
// ============================================================================

class AnalysisCacheImpl implements AnalysisCacheStore {
  private readonly db: Database.Database;
  private readonly stmtGet: Database.Statement;
  private readonly stmtSet: Database.Statement;
  private readonly stmtGetAll: Database.Statement;

  constructor(dbPath?: string) {
    const resolvedPath = resolve(dbPath ?? process.env["DB_PATH"] ?? DEFAULT_DB_PATH);

    const dir = dirname(resolvedPath);
    if (!existsSync(dir)) {
      mkdirSync(dir, { recursive: true });
    }

    this.db = new Database(resolvedPath);
    this.db.pragma("journal_mode = WAL");
    this.db.pragma("synchronous = NORMAL");

    this.initSchema();

    this.stmtGet = this.db.prepare(
      `SELECT data FROM episode_cache WHERE episode_id = ?`,
    );

    this.stmtSet = this.db.prepare(
      `INSERT OR REPLACE INTO episode_cache (episode_id, data, created_at)
       VALUES (?, ?, ?)`,
    );

    this.stmtGetAll = this.db.prepare(
      `SELECT data FROM episode_cache ORDER BY created_at DESC`,
    );
  }

  get(episodeId: string): EpisodeExtraction | null {
    const row = this.stmtGet.get(episodeId) as { data: string } | undefined;
    if (!row) return null;
    try {
      return JSON.parse(row.data) as EpisodeExtraction;
    } catch {
      return null;
    }
  }

  set(episodeId: string, data: EpisodeExtraction): void {
    const now = Math.floor(Date.now() / 1000);
    this.stmtSet.run(episodeId, JSON.stringify(data), now);
  }

  getAll(): EpisodeExtraction[] {
    const rows = this.stmtGetAll.all() as Array<{ data: string }>;
    const results: EpisodeExtraction[] = [];
    for (const row of rows) {
      try {
        results.push(JSON.parse(row.data) as EpisodeExtraction);
      } catch {
        // Skip corrupted entries
      }
    }
    return results;
  }

  close(): void {
    this.db.close();
  }

  private initSchema(): void {
    this.db.exec(`
      CREATE TABLE IF NOT EXISTS episode_cache (
        episode_id TEXT PRIMARY KEY,
        data       TEXT NOT NULL,
        created_at INTEGER NOT NULL
      );

      CREATE INDEX IF NOT EXISTS idx_episode_cache_created
        ON episode_cache(created_at);
    `);
  }
}

// ============================================================================
// FACTORY
// ============================================================================

/**
 * Create an analysis cache backed by SQLite.
 *
 * @param dbPath - Optional path to the SQLite database file.
 *   Defaults to ./data/cache.db or DB_PATH env var.
 *   Pass ":memory:" for an in-memory database (useful in tests).
 * @returns AnalysisCacheStore with get/set/getAll methods
 */
export function createAnalysisCache(dbPath?: string): AnalysisCacheStore {
  return new AnalysisCacheImpl(dbPath);
}

/**
 * SQLite cache + usage metering for Podcast Commerce MCP.
 *
 * Two concerns in one file (both lightweight):
 * 1. ExtractionCache — stores extraction results keyed by episode_id
 * 2. UsageTracker — tracks daily free-tier calls per agent, records usage events
 */

import Database from "better-sqlite3";
import { existsSync, mkdirSync } from "node:fs";
import { resolve } from "node:path";
import type { ExtractionResult } from "./types.js";

// ============================================================================
// CONSTANTS
// ============================================================================

const DEFAULT_DB_PATH = "./data/cache.db";
/** Free tier calls per day per agent. */
const FREE_TIER_DAILY_LIMIT = 5;

// ============================================================================
// CACHE
// ============================================================================

export interface CacheEntry {
  episode_id: string;
  data: ExtractionResult;
  created_at: number;
}

export class PodcastCache {
  private readonly db: Database.Database;

  // Prepared statements
  private readonly stmtGet: Database.Statement;
  private readonly stmtSet: Database.Statement;
  private readonly stmtGetDailyCount: Database.Statement;
  private readonly stmtRecordUsage: Database.Statement;

  constructor(dbPath?: string) {
    const rawPath = dbPath ?? process.env["CACHE_DIR"] ?? DEFAULT_DB_PATH;
    const resolvedPath = rawPath === ":memory:" ? ":memory:" : resolve(rawPath);

    // Ensure directory exists
    const dir = resolvedPath.substring(0, resolvedPath.lastIndexOf("/"));
    if (dir && !existsSync(dir)) {
      mkdirSync(dir, { recursive: true });
    }

    this.db = new Database(resolvedPath);
    this.db.pragma("journal_mode = WAL");
    this.db.pragma("synchronous = NORMAL");

    this.initSchema();

    this.stmtGet = this.db.prepare(
      `SELECT data FROM extraction_cache WHERE episode_id = ?`
    );

    this.stmtSet = this.db.prepare(
      `INSERT OR REPLACE INTO extraction_cache (episode_id, data, created_at)
       VALUES (?, ?, ?)`
    );

    this.stmtGetDailyCount = this.db.prepare(
      `SELECT COUNT(*) as count FROM usage_events
       WHERE agent_id = ? AND DATE(timestamp, 'unixepoch') = DATE('now')`
    );

    this.stmtRecordUsage = this.db.prepare(
      `INSERT INTO usage_events (agent_id, tool_name, timestamp, payment_method, amount_usd, success)
       VALUES (?, ?, ?, ?, ?, ?)`
    );
  }

  // --------------------------------------------------------------------------
  // Extraction cache
  // --------------------------------------------------------------------------

  get(episodeId: string): ExtractionResult | null {
    const row = this.stmtGet.get(episodeId) as { data: string } | undefined;
    if (!row) return null;
    try {
      return JSON.parse(row.data) as ExtractionResult;
    } catch {
      return null;
    }
  }

  set(episodeId: string, result: ExtractionResult): void {
    const now = Math.floor(Date.now() / 1000);
    this.stmtSet.run(episodeId, JSON.stringify(result), now);
  }

  // --------------------------------------------------------------------------
  // Free tier metering
  // --------------------------------------------------------------------------

  /**
   * Check if agent is within free tier limit.
   * Returns true if the call is allowed.
   */
  checkFreeTier(agentId: string): boolean {
    const row = this.stmtGetDailyCount.get(agentId) as { count: number };
    return row.count < FREE_TIER_DAILY_LIMIT;
  }

  /**
   * Get the number of free calls used today by this agent.
   */
  getFreeTierUsed(agentId: string): number {
    const row = this.stmtGetDailyCount.get(agentId) as { count: number };
    return row.count;
  }

  /**
   * Record a tool usage event.
   */
  recordUsage(params: {
    agentId: string;
    toolName: string;
    paymentMethod: string;
    amountUsd: number;
    success: boolean;
  }): void {
    const now = Math.floor(Date.now() / 1000);
    this.stmtRecordUsage.run(
      params.agentId,
      params.toolName,
      now,
      params.paymentMethod,
      params.amountUsd,
      params.success ? 1 : 0
    );
  }

  // --------------------------------------------------------------------------
  // Lifecycle
  // --------------------------------------------------------------------------

  close(): void {
    this.db.close();
  }

  // --------------------------------------------------------------------------
  // Private
  // --------------------------------------------------------------------------

  private initSchema(): void {
    this.db.exec(`
      CREATE TABLE IF NOT EXISTS extraction_cache (
        episode_id TEXT PRIMARY KEY,
        data       TEXT NOT NULL,
        created_at INTEGER NOT NULL
      );

      CREATE TABLE IF NOT EXISTS usage_events (
        id             INTEGER PRIMARY KEY AUTOINCREMENT,
        agent_id       TEXT NOT NULL,
        tool_name      TEXT NOT NULL,
        timestamp      INTEGER NOT NULL,
        payment_method TEXT,
        amount_usd     REAL DEFAULT 0,
        success        INTEGER DEFAULT 1
      );

      CREATE INDEX IF NOT EXISTS idx_usage_agent_day
        ON usage_events(agent_id, timestamp);
    `);
  }
}

// ============================================================================
// FACTORY
// ============================================================================

let _instance: PodcastCache | null = null;

/**
 * Get the shared cache instance (singleton per process).
 * Pass a custom dbPath on first call to override the default location.
 */
export function getCache(dbPath?: string): PodcastCache {
  if (!_instance) {
    _instance = new PodcastCache(dbPath);
  }
  return _instance;
